  box-shadow: none;
}

.ds-workspace-start .ds-prompt-suggestions {
  order: 2;
  align-items: stretch;
  gap: var(--space-related);
  margin: var(--space-panel) 0 0;
}

.ds-workspace-start .ds-prompt-suggestions button {
  justify-content: flex-start;
  text-align: left;
  gap: var(--space-related);
  min-height: 104px;
  padding: var(--space-related);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.ds-workspace-start .ds-prompt-suggestions button:hover {
  border-color: var(--line-control);
  background: var(--surface-hover);
}

.ds-example-artwork {
  width: 64px;
  height: 64px;
  flex-shrink: 0;
  fill: none;
  stroke: var(--text-secondary);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ds-example-cell-filled {
  fill: var(--text-secondary);
}

.ds-example-copy {
  display: flex;
  flex-direction: column;
  gap: var(--space-control);
  min-width: 0;
}

.ds-example-copy strong {
  color: var(--ink);
  font-weight: 600;
}

.ds-example-copy > span {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--text-muted);
  font-size: var(--type-metadata);
}

@media (max-width: 800px) {
  .ds-workspace-start {
    padding-block: var(--space-panel);
  }

  .ds-workspace-start .ds-prompt-suggestions {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-control);
  }

  .ds-workspace-start .ds-prompt-suggestions button {
    min-height: 80px;
  }

  .ds-example-artwork {
    width: 48px;
    height: 48px;
  }
}

@media(prefers-reduced-motion:reduce){.ds-example-sample *{animation:none!important;transition:none!important;}}
.ds-example-sample .ds-prompt-suggestions{grid-template-columns:minmax(0,1fr)}
